function o(r){return r?r.replace(/\*\*状态\*\*：\s*[A-Z_]+（(\d+)\/(\d+) 个步骤成功）/g,"**步骤**：$1/$2 成功"):""}function e(r){if(r==null||!isFinite(r)||r<=0)return"—";const t=Math.round(r);if(t<60)return`${t} 秒`;const n=Math.floor(t/60),i=t%60;return n<60?i?`${n} 分 ${i} 秒`:`${n} 分`:`${Math.floor(n/60)} 小时 ${n%60} 分`}function f(r){return r==null||!isFinite(r)?"—":r>=1?`$${r.toFixed(2)}`:`$${r.toFixed(4)}`}function a(r){if(r==null||r==="")return"时间未知";const t=new Date(r);return isNaN(t.getTime())?"时间未知":t.toLocaleString()}export{f as a,e as b,a as f,o as n};
